from pypdf import PdfReader
from pathlib import Path
import re
r=PdfReader('manuscript.pdf')
for i in [3,10,11,12,13,14,15]:
 t=Path(f'tmp/pdfs/page-{i+1:02d}.txt').read_text()
 def dec(m):
  n=int(m.group(1),16)
  return chr(n+29) if n<127 else {237:'−'}.get(n,'?')
 t=re.sub(r'/uni([0-9a-fA-F]{8})', dec, t)
 Path(f'tmp/pdfs/decoded-{i+1:02d}.txt').write_text(t)
 if i>=12: print(f'===== PAGE {i+1} =====\\n'+t[:22000])
print('===== LINKS SAMPLE =====')
for i in [0,4,5]:
 links=[]
 for a in r.pages[i].get('/Annots',[]):
  a=a.get_object()
  act=a.get('/A')
  if act and '/URI' in act: links.append(str(act['/URI']))
 print('Page',i+1,'links',len(links),links[:7])
PY"
